from taf.sbts.oam.coam.admin.schemas.procedure.lte_ccm_uplink import LTECCMUplink


class LTECCMUplinkPucchCqi(LTECCMUplink):
    def __init__(self, lncel_rdn, measurement_type, reporting_time_interval, reception_subframe,
                 exception_subframe, earfcn, index_cqi, index_second=None, index_third=None, index_fourth=None,
                 root_seq_index=None, prach_cs=None, prach_hs_flag=None, phys_cell_id=None, tdd_frame_conf=None,
                 tdd_spec_subf_conf=None):
        super(LTECCMUplinkPucchCqi, self).__init__(lncel_rdn=lncel_rdn,
                                                   measurement_type=measurement_type,
                                                   reporting_time_interval=reporting_time_interval,
                                                   reception_subframe=reception_subframe,
                                                   exception_subframe=exception_subframe,
                                                   earfcn=earfcn,
                                                   root_seq_index=root_seq_index,
                                                   prach_cs=prach_cs,
                                                   prach_hs_flag=prach_hs_flag,
                                                   phys_cell_id=phys_cell_id,
                                                   tdd_frame_conf=tdd_frame_conf,
                                                   tdd_spec_subf_conf=tdd_spec_subf_conf)

        self.pucch_cqi_params = {"pucchResourceIndexCqi": self.validate_param('pucchResourceIndexCqi',
                                                                              index_cqi,
                                                                              [0, 1185]),
                                 "pucchResourceIndexSecond": self.validate_param('pucchResourceIndexSecond',
                                                                                 index_second,
                                                                                 [0, 1185]),
                                 "pucchResourceIndexThird": self.validate_param('pucchResourceIndexThird',
                                                                                index_third,
                                                                                [0, 1185]),
                                 "pucchResourceIndexFourth": self.validate_param('pucchResourceIndexFourth',
                                                                                 index_fourth,
                                                                                 [0, 1185])
                                 }

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_pucch_cqi_param(parameter):
            return response_dict['params']['pucchCqiParams'][parameter]

        lncel_rdn = response_dict['lncel_rDN']
        measurement_type = response_dict['params']['measurementType']
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        reception_subframe = response_dict['params']['receptionSubframe']
        exception_subframe = response_dict['params']['expectionSubframe']
        earfcn = response_dict['params']['earfcn']
        root_seq_index = response_dict['params']['rootSeqIndex'] if 'rootSeqIndex' in response_dict['params'] else None
        prach_cs = response_dict['params']['prachCS'] if 'prachCS' in response_dict['params'] else None
        prach_hs_flag = response_dict['params']['prachHsFlag'] if 'prachHsFlag' in response_dict['params'] else None
        phys_cell_id = response_dict['params']['physCellId'] if 'physCellId' in response_dict['params'] else None
        tdd_frame_conf = response_dict['params']['tddFrameConf'] if 'tddFrameConf' in response_dict['params'] else None
        tdd_spec_subf_conf = response_dict['params']['tddSpecSubfConf'] if 'tddSpecSubfConf' in response_dict[
            'params'] else None

        pucch_cqi_params = {"pucchResourceIndexCqi": _get_pucch_cqi_param('pucchResourceIndexCqi'),
                            "pucchResourceIndexSecond": _get_pucch_cqi_param('pucchResourceIndexSecond'),
                            "pucchResourceIndexThird": _get_pucch_cqi_param('pucchResourceIndexThird'),
                            "pucchResourceIndexFourth": _get_pucch_cqi_param('pucchResourceIndexFourth')}

        return cls(lncel_rdn=lncel_rdn,
                   measurement_type=measurement_type,
                   reporting_time_interval=reporting_time_interval,
                   reception_subframe=reception_subframe,
                   exception_subframe=exception_subframe,
                   earfcn=earfcn,
                   index_cqi=pucch_cqi_params["pucchResourceIndexCqi"],
                   index_second=pucch_cqi_params["pucchResourceIndexSecond"],
                   index_third=pucch_cqi_params["pucchResourceIndexThird"],
                   index_fourth=pucch_cqi_params["pucchResourceIndexFourth"],
                   root_seq_index=root_seq_index,
                   prach_cs=prach_cs,
                   prach_hs_flag=prach_hs_flag,
                   phys_cell_id=phys_cell_id,
                   tdd_frame_conf=tdd_frame_conf,
                   tdd_spec_subf_conf=tdd_spec_subf_conf)

    def as_dict(self):
        attributes = super(LTECCMUplinkPucchCqi, self).as_dict()
        self.pucch_cqi_params = self.filter_empty_parameters(self.pucch_cqi_params)
        attributes['params']['pucchCqiParams'] = self.pucch_cqi_params

        return attributes
